INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Product Owner auch Entwickler?', 2, '[{"text": "Nein", "correct": true, "because": "Getrennte Rollen"}, {"text": "Ja", "correct": false, "because": "Fokus auf Produktvision"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle definiert die Produktziele?', 3, '[{"text": "Product Owner", "correct": true, "because": "Verantwortlich für Vision"}, {"text": "Scrum Master", "correct": false, "because": "Prozessunterstützung"}, {"text": "Entwickler", "correct": false, "because": "Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen sind für den Erfolg entscheidend?', 5, '[{"text": "Product Owner", "correct": true, "because": "Priorisiert Anforderungen"}, {"text": "Entwickler", "correct": true, "because": "Erstellt das Produkt"}, {"text": "Externer Chef", "correct": false, "because": "Team-intern"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Scrum Master hilft dem Team. b) Entwickler definieren Ziele.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ziele vom Product Owner"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Aufgabenverteilung?', 4, '[{"text": "Product Owner", "correct": false, "because": "Ziele setzen"}, {"text": "Scrum Master", "correct": false, "because": "Prozess fördern"}, {"text": "Zufällige Rollen", "correct": true, "because": "Definierte Verantwortlichkeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Scrum Master programmiert?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Prozess"}, {"text": "Ja", "correct": false, "because": "Entwickler übernehmen das"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle unterstützt das Team bei Hindernissen?', 3, '[{"text": "Scrum Master", "correct": true, "because": "Entfernt Blockaden"}, {"text": "Product Owner", "correct": false, "because": "Fokus auf Produkt"}, {"text": "Entwickler", "correct": false, "because": "Fokus auf Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernehmen diese Rollen?', 5, '[{"text": "Entwickler bauen Produkt", "correct": true, "because": "Technische Umsetzung"}, {"text": "Product Owner priorisiert", "correct": true, "because": "Definiert Backlog"}, {"text": "Scrum Master entwickelt", "correct": false, "because": "Prozessstütze"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Product Owner steuert Vision. b) Scrum Master ist der Boss. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Scrum Master führt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Entwickler", "correct": false, "because": "Produkt erstellen"}, {"text": "Product Owner", "correct": false, "because": "Ziele definieren"}, {"text": "Externer Manager", "correct": true, "because": "Team-intern geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Product Owner für den Prozess zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Scrum Master übernimmt"}, {"text": "Ja", "correct": false, "because": "Fokus auf Produkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen fördern die Zusammenarbeit?', 4, '[{"text": "Scrum Master", "correct": true, "because": "Team unterstützen"}, {"text": "Entwickler", "correct": true, "because": "Produkt gemeinsam bauen"}, {"text": "Alleinerziehender Chef", "correct": false, "because": "Team-orientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Entwickler die Ziele setzen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Product Owner definiert"}, {"text": "Ja", "correct": false, "because": "Entwickler umsetzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich als Product Owner?', 3, '[{"text": "Backlog-Priorisierung", "correct": true, "because": "Wichtigkeit festlegen"}, {"text": "Code schreiben", "correct": false, "because": "Entwickler-Aufgabe"}, {"text": "Prozess steuern", "correct": false, "because": "Scrum Master"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Entwickler liefern das Produkt. b) Scrum Master priorisiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Priorisierung vom Product Owner"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Rollen?', 5, '[{"text": "Klare Verantwortung", "correct": true, "because": "Aufgaben geteilt"}, {"text": "Effiziente Umsetzung", "correct": true, "because": "Team abgestimmt"}, {"text": "Einzelentscheidungen", "correct": false, "because": "Team-orientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier unwichtig?', 3, '[{"text": "Product Owner", "correct": false, "because": "Ziele setzen"}, {"text": "Entwickler", "correct": false, "because": "Produkt bauen"}, {"text": "Zufällige Führung", "correct": true, "because": "Definierte Rollen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Scrum Master für das Produkt verantwortlich?', 3, '[{"text": "Nein", "correct": true, "because": "Product Owner übernimmt"}, {"text": "Ja", "correct": false, "because": "Fokus auf Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Entwickler den Prozess steuern?', 2, '[{"text": "Nein", "correct": true, "because": "Scrum Master unterstützt"}, {"text": "Ja", "correct": false, "because": "Entwickler bauen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle wähle ich für Produktvision?', 4, '[{"text": "Product Owner", "correct": true, "because": "Definiert Richtung"}, {"text": "Scrum Master", "correct": false, "because": "Prozesshilfe"}, {"text": "Entwickler", "correct": false, "because": "Umsetzung"}]');
